const std = @import("std");

/// Documented encodings shared by CPU, assembler and disassembler.
/// Placeholders: b=u8, w=u16, r=relative target, d=signed index displacement.
pub const Definition = struct {
    prefix: u8 = 0,
    opcode: u8,
    indexed_cb: bool = false,
    legacy: bool = false,
    pattern: []const u8,
    t_states: u16,
    taken_t_states: u16 = 0,
    flag_effects: []const u8 = "instruction-specific documented flags",
    pub fn flagEffects(self: Definition) []const u8 {
        const p = self.pattern;
        const end = std.mem.indexOfScalar(u8, p, ' ') orelse p.len;
        const name = p[0..end];
        if (std.mem.eql(u8, p, "LD A,I") or std.mem.eql(u8, p, "LD A,R")) return "SZ; H=N=0; PV=IFF2; C kept";
        if (std.mem.startsWith(u8, p, "ADD HL,") or std.mem.startsWith(u8, p, "ADD IX,") or std.mem.startsWith(u8, p, "ADD IY,")) return "HNC; SZPV kept";
        if (std.mem.eql(u8, name, "INC") or std.mem.eql(u8, name, "DEC")) {
            if (self.t_states == 6 or self.t_states == 10) return "kept";
            return "SZHPVN; C kept";
        }
        if (std.mem.startsWith(u8, name, "BIT")) return "SZHPVN; C kept";
        if (std.mem.eql(u8, name, "IN")) return if (self.prefix == 0xed) "SZHPVN; C kept" else "kept";
        if (std.mem.eql(u8, name, "CPL")) return "H=N=1; SZPVC kept";
        if (std.mem.eql(u8, name, "SCF") or std.mem.eql(u8, name, "CCF") or std.mem.eql(u8, name, "RLCA") or std.mem.eql(u8, name, "RRCA") or std.mem.eql(u8, name, "RLA") or std.mem.eql(u8, name, "RRA")) return "HNC; SZPV kept";
        if (std.mem.startsWith(u8, name, "LDI") or std.mem.startsWith(u8, name, "LDD")) return "H=N=0; PV=BC!=0; SZC kept";
        if (std.mem.startsWith(u8, name, "CPI") or std.mem.startsWith(u8, name, "CPD")) return "SZHN; PV=BC!=0; C kept";
        if (std.mem.eql(u8, name, "ADD") or std.mem.eql(u8, name, "ADC") or std.mem.eql(u8, name, "SUB") or std.mem.eql(u8, name, "SBC") or std.mem.eql(u8, name, "CP") or std.mem.eql(u8, name, "AND") or std.mem.eql(u8, name, "OR") or std.mem.eql(u8, name, "XOR") or std.mem.eql(u8, name, "NEG") or std.mem.eql(u8, name, "DAA")) return "SZHPVNC";
        if (std.mem.startsWith(u8, name, "RL") or std.mem.startsWith(u8, name, "RR") or std.mem.startsWith(u8, name, "SL") or std.mem.startsWith(u8, name, "SR") or std.mem.startsWith(u8, name, "IN") or std.mem.startsWith(u8, name, "OUTI") or std.mem.startsWith(u8, name, "OUTD") or std.mem.startsWith(u8, name, "OT")) return "SZHPVNC (RRD/RLD keep C)";
        if (std.mem.eql(u8, p, "POP AF") or std.mem.eql(u8, p, "EX AF,AF'")) return "loaded/exchanged";
        return "kept";
    }
    pub fn size(self: Definition) u8 {
        var n: u8 = if (self.prefix == 0) 1 else if (self.indexed_cb) 3 else 2;
        for (self.pattern, 0..) |ch, i| if (ch == '{') {
            n += if (self.pattern[i + 1] == 'w') 2 else 1;
        };
        return n;
    }
};

