pub fn lookup(prefix: u8, opcode: u8) ?Definition {
    for (definitions) |definition| if (!definition.indexed_cb and definition.prefix == prefix and definition.opcode == opcode) return definition;
    return null;
}

pub const Match = struct { values: [2][]const u8 = .{ "", "" }, kinds: [2]u8 = .{ 0, 0 }, len: usize = 0 };
pub fn match(pattern: []const u8, text: []const u8) ?Match {
    var result: Match = .{};
    var p: usize = 0;
    var t: usize = 0;
    while (p < pattern.len) {
        if (pattern[p] != '{') {
            if (t == text.len or pattern[p] != text[t]) return null;
            p += 1;
            t += 1;
            continue;
        }
        const kind = pattern[p + 1];
        p += 3;
        const start = t;
        if (p == pattern.len) t = text.len else {
            while (t < text.len and text[t] != pattern[p]) t += 1;
        }
        if (t == start or result.len == 2) return null;
        if (std.mem.indexOfAny(u8, text[start..t], "()") != null) return null;
        result.values[result.len] = text[start..t];
        result.kinds[result.len] = kind;
        result.len += 1;
    }
    return if (t == text.len) result else null;
}

pub fn isMnemonic(name: []const u8) bool {
    for (definitions) |definition| {
        const end = std.mem.indexOfScalar(u8, definition.pattern, ' ') orelse definition.pattern.len;
        if (std.ascii.eqlIgnoreCase(name, definition.pattern[0..end])) return true;
    }
    return false;
}

pub fn lookupIndexedCb(prefix: u8, opcode: u8) ?Definition {
    for (definitions) |definition| if (definition.indexed_cb and definition.prefix == prefix and definition.opcode == opcode) return definition;
    return null;
}
